@kt.kernel
def k(x=kt.In(8, 32), y=kt.Out(8, 32), m=kt.Out(8)):
    for c in kt.par(2, on=kt.vc):
        for t in kt.range(1):
            r = c * 4 + t * 4
            v = kt.load(x[r : r + 4, :], gt4=True)
            s = kt.rsum(v)
            kt.store(y[r : r + 4, :], v * s)
            kt.store(m[r : r + 4], s)
